function insert(node, v) {
  if (node === null) return { value: v, left: null, right: null };
  if (v < node.value) node.left = insert(node.left, v);
  else if (v > node.value) node.right = insert(node.right, v);
  return node;                      // equal: already present, do nothing
}

function contains(node, v) {
  while (node !== null) {
    if (v === node.value) return true;
    node = v < node.value ? node.left : node.right;
  }
  return false;
}

function isBST(n, lo = -Infinity, hi = Infinity) {
  if (n === null) return true;
  if (n.value <= lo || n.value >= hi) return false;
  return isBST(n.left, lo, n.value) && isBST(n.right, n.value, hi);
}

