function bstInsertAll(values) {
  let root = null;
  const insert = (n, v) => {
    if (n === null) return { value: v, left: null, right: null };
    if (v < n.value) n.left = insert(n.left, v);
    else if (v > n.value) n.right = insert(n.right, v);
    return n;
  };
  const walk = (n, out) => {
    if (n === null) return out;
    walk(n.left, out);
    out.push(n.value);
    walk(n.right, out);
    return out;
  };
  for (const v of values) root = insert(root, v);
  return walk(root, []);
}

