function minValue(n) {
  while (n.left !== null) n = n.left;
  return n.value;
}

function remove(n, v) {
  if (n === null) return null;
  if (v < n.value) { n.left = remove(n.left, v); return n; }
  if (v > n.value) { n.right = remove(n.right, v); return n; }

  if (n.left === null) return n.right;   // leaf, or right child only
  if (n.right === null) return n.left;   // left child only

  n.value = minValue(n.right);           // two children: take the successor
  n.right = remove(n.right, n.value);
  return n;
}

