implementation.solution:
function bstDepthOf(values, target) {
  let root = null;
  const insert = (n, v) => {
    if (n === null) return { value: v, left: null, right: null };
    if (v < n.value) n.left = insert(n.left, v);
    else if (v > n.value) n.right = insert(n.right, v);
    return n;
  };
  for (const v of values) root = insert(root, v);
  let depth = 0, cur = root;
  while (cur !== null) {
    if (cur.value === target) return depth;
    cur = target < cur.value ? cur.left : cur.right;
    depth++;
  }
  return -1;
}

